function drawScorbunnyFireRabbit(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.8;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(Math.sin(breathPhase)) * 4.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 24 * (1.0 - 0.2 * Math.abs(Math.sin(breathPhase))), 5, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Thân
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 12 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.roundRect(-7, by + 4, 14, 4, 2); ctx.fill();

  // 3. Hai chân sau
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.roundRect(-14, by + 20, 6, 18, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6,   by + 16, 6, 18, 3); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.roundRect(-15, by + 32, 8, 7, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6,   by + 28, 8, 7, 2); ctx.fill();
  ctx.fillStyle = '#facc15';
  ctx.fillRect(-14, by + 34, 6, 3);
  ctx.fillRect(7,   by + 30, 6, 3);

  // 4. Tay
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.roundRect(-18, by + 8, 8, 5, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(10,  by + 8, 8, 5, 2); ctx.fill();

  // 5. Đầu
  ctx.beginPath(); ctx.arc(0, by - 8, 16 * sX, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-16, by - 8); ctx.lineTo(-24, by - 6); ctx.lineTo(-14, by - 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(16,  by - 8); ctx.lineTo(24,  by - 6); ctx.lineTo(14,  by - 2); ctx.fill();

  // 6. Tai
  [-14, 6].forEach((x, i) => {
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.roundRect(x, by - 38, 8, 26, 4); ctx.fill();
    ctx.fillStyle = '#f97316';
    ctx.beginPath(); ctx.roundRect(x, by - 38, 8, 12, 4); ctx.fill();
    ctx.fillStyle = '#facc15';
    ctx.beginPath(); ctx.roundRect(x + 2, by - 28, 4, 12, 2); ctx.fill();
  });

  // 7. Băng gạc mũi
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.roundRect(-5, by - 8, 10, 5, 2); ctx.fill();

  // 8. Miệng cười lộ răng
  ctx.fillStyle = '#991b1b';
  ctx.beginPath(); ctx.arc(0, by + 1, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-2, by - 1, 4, 3);

  // 9. Mắt
  if (!blink) {
    ctx.fillStyle = '#d97706';
    ctx.beginPath(); ctx.ellipse(-7, by - 10, 3, 5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(7,  by - 10, 3, 5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-8, by - 12, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(6,  by - 12, 1.2, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#d97706'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-9, by - 9); ctx.lineTo(-5, by - 9); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(5,  by - 9); ctx.lineTo(9,  by - 9); ctx.stroke();
  }

  ctx.restore();
}
